using System;

public class IDelayProviderTests
{
[Fact]
public async Task DelayAsync_CancelledBeforeCompletion_ThrowsTaskCanceledException()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource();
    var delayTask = delayProvider.DelayAsync(1000, cts.Token);

    // Act
