[Fact]
public async Task DelayAsync_WithCancellationToken_CompletesSuccessfully()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource();
    int delayMilliseconds = 100;

    // Act
    var delayTask = delayProvider.DelayAsync(delayMilliseconds, cts.Token);
    
    // Assert
    await Task.WhenAny(delayTask, Task.Delay(delayMilliseconds * 2));
    Assert.True(delayTask.IsCompleted, "The delay task should complete successfully.");
    Assert.False(delayTask.IsCanceled, "The delay task should not be cancelled.");

[Fact]
public async Task DelayAsync_WithZeroMilliseconds_ReturnsImmediately()
{
    // Arrange
    IDelayProvider delayProvider = new DelayProvider();
    int milliseconds = 0;
    
    // Act
    var startTime = DateTime.UtcNow;
    await delayProvider.DelayAsync(milliseconds);
    var elapsedTime = DateTime.UtcNow - startTime;
    
    // Assert
    Assert.True(elapsedTime.TotalMilliseconds < 10, 
        $"Expected delay to return immediately, but it took {elapsedTime.TotalMilliseconds} ms");

[Fact]
public async Task DelayAsync_WithCancellationTokenNone_ShouldCompleteWithoutCancellation()
{
    // Arrange
    IDelayProvider delayProvider = new DelayProvider();
    int delayMilliseconds = 100;
    
    // Act
    var delayTask = delayProvider.DelayAsync(delayMilliseconds, CancellationToken.None);
    
    // Assert
